  'Schäbige Bar' =>
	'Shabby Bar',
  'Unbewohntes Einfamilienhaus' =>
	'Uninhabited House',
  'Apotheke "Hypochonders bester Freund"' =>
	'Pharmacy "Valetudinarian Vault"',
  'Gate\'s Motel' =>
